Definition DEREF_STACK : Z := 16.

(* [comment removed for export] *)
Definition SrCells (bq beg en bpos lpos : Z) : list cell :=
  [C8 (wz bq); C8 (wz beg); C8 (wz en); C8 (wz bpos); C8 (wz lpos)].

Definition deref_len0 (x pe lpos sx : Z) : Z := if x =? pe then lpos else sx.
Definition deref_res (x beg pe bpos lpos sx : Z) : Z * Z :=
  let l0 := deref_len0 x pe lpos sx in
  if x =? beg then (x + 24 + Z.min bpos l0, l0 - Z.min bpos l0) else (x + 24, l0).

Definition deref_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (x beg pe bpos lpos sx lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (fst (deref_res x beg pe bpos lpos sx))) (wz (snd (deref_res x beg pe bpos lpos sx)))
                  a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp).

Definition deref_stmt : Prop := forall (itp sr x bq beg en bpos lpos pe sx lo : Z) (w0 : word) (reste restx : list cell)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells rsegs m itp [C8 (wz sr); C8 (wz x)] ->
  rw_cells rsegs m sr (SrCells bq beg en bpos lpos) ->
  rw_cells rsegs m en (C8 w0 :: C8 (wz pe) :: reste) ->
  rw_cells rsegs m (x + 16) (C8 (wz sx) :: restx) ->
  1 <= lpos < 2^64 -> 0 <= bpos < 2^64 -> 0 <= sx < 2^64 -> 0 <= beg < 2^64 -> 0 <= pe < 2^64 -> 0 < x -> x + 24 + sx < 2^64 ->
  stk rsegs m lo (bv_unsigned sp) -> lo + DEREF_STACK <= bv_unsigned sp -> hceil <= lo ->
  (itp + 16 <= bv_unsigned sp - 16 \/ bv_unsigned sp <= itp) ->
  (sr + 40 <= bv_unsigned sp - 16 \/ bv_unsigned sp <= sr) ->
  (en + Z.of_nat (cells_size (C8 w0 :: C8 (wz pe) :: reste)) <= bv_unsigned sp - 16 \/ bv_unsigned sp <= en) ->
  (x + 16 + Z.of_nat (cells_size (C8 (wz sx) :: restx)) <= bv_unsigned sp - 16 \/ bv_unsigned sp <= x + 16) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (deref_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc x beg pe bpos lpos sx lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz itp) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_MB_SUBRANGE_DEREF) fc None m (seg_rom rsegs)).
