Definition sr_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (res b : Z) (es : list mbe) (insz n x : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz res) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(res, res + 40)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ rw_cells rsegs m' res (SrCells b (mb_mid_out b es insz x) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n))
    /\ MBmid m' b es insz n x.

Definition sr_stmt : Prop := forall (res b : Z) (es : list mbe) (insz n x : Z) (rj : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  MBmid m b es insz n x -> mb_ok es insz -> 1 <= n -> insz + n <= 2^30 ->
  rw_cells rsegs m res [CB 40 rj] -> hceil <= res -> (res + 40 <= b \/ b + 64 <= res) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (sr_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc res b es insz n x m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz res) (wz b) (wz insz) (wz n) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_MB_SUBRANGE_CTOR) fc None m (seg_rom rsegs)).

(* [comment removed for export] *)
Lemma MBmid_after_res : forall m m' b es insz n x res,
  MBmid m b es insz n x -> munch [(res, res + 40)]%Z m m' -> wmono rsegs m m' -> hceil <= res -> (res + 40 <= b \/ b + 64 <= res) ->
  MBmid m' b es insz n x.
Proof.
  intros m m' b es insz n x res MID MU WM R1 R2. unfold MBmid in *.
  pose proof MID as (ls & _ & _ & _ & _ & _ & AOK). pose proof AOK as (AD & _).
  eapply MBraw_transport_gen; [exact MID| exact MU| exact WM| cbn; lia|].
  intros x' s' IN. destruct (AD x' s' IN) as (P & _ & S0 & R). cbn. lia.
Qed.

